function openModal(title,body,submitLabel='Guardar',onSubmit=null){$('#modalRoot').innerHTML=`<div class="modalback" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modalhead"><h2>${title}</h2><button class="xbtn" data-action="close-modal" aria-label="Cerrar">×</button></div><form id="activeForm">${body}<div class="modalactions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${submitLabel}</button></div></form></section></div>`;$('#activeForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!onSubmit||form.dataset.busy==='1')return;form.dataset.busy='1';try{await onSubmit(new FormData(form),form)}catch(err){console.error(err);notify('No se pudo completar la operación. Revisa el archivo.')}finally{form.dataset.busy='0'}});}
